 const originTotals=new Map();for(const o of imports)originTotals.set(o.partner_iso3,(originTotals.get(o.partner_iso3)||0)+(o.value_usd||0));const labelled=new Set(['KAZ','KGZ','RUS',...[...originTotals].sort((a,b)=>b[1]-a[1]).slice(0,5).map(([code])=>code)]);
