 $('#rt-status').textContent=state.frequency==='A'?tr('Roční pohled · všechny vykázané země původu · referenční rok 2019. Kazachstán 2020–2022: dostupný detail je pod národními součty; viz metodika.','Annual view · all reported origins · reference year 2019. Kazakhstan 2020–2022: available detail is below national totals; see methodology.'):tr('Měsíční detail je dostupný od roku 2024; předválečné měsíce chybí. Roční historie zůstává dostupná přepínačem. Mezery nejsou nuly.','Monthly detail is available from 2024; pre-war months are missing. Switch to Annual for the historical comparison. Gaps are not zeros.');
