// Authored annual delta layer. Its all-goods accounting is independent of explorer filters.
const story={country:/^[A-Z]{3}$/.test(params.get('story_country')||'')&&params.get('story_country')!=='RUS'?params.get('story_country'):'CHN',year:/^20\d{2}$/.test(params.get('story_year')||'')&&params.get('story_year')>'2019'?params.get('story_year'):null,data:null,bilateral:null,cache:new Map(),charts:[],request:0};
const storyPalette=['#a8b63f','#537b84','#bd923f','#89738b','#427c68','#d2ccc1'];
const decimal=v=>{if(v===null||v===undefined)return '—';const [whole,fraction]=String(v).split('.');return (whole==='-0'?'-':'')+new Intl.NumberFormat(locale).format(BigInt(whole))+(fraction?(lang==='cs'?',':'.')+fraction:'');},exactUSD=v=>`${decimal(v)} USD`;
const deltaColumns=[{key:'label',label:tr('Kategorie / země','Category / country')},{key:'baseExact',label:'2019 USD'},{key:'valueExact',label:tr('Srovnávací rok USD','Comparison year USD')},{key:'deltaExact',label:'Δ USD'},{key:'sharePositiveExact',label:tr('Podíl kladných změn %','Share of positive changes %')},{key:'memberCodes',label:tr('Zahrnuté kódy','Included codes')}];
function clearStory(){$('#rt-story-download').disabled=true;story.charts.forEach(c=>c.destroy());story.charts=[];for(const id of ['rt-story-suppliers','rt-story-supplier-declines','rt-story-supplier-copy','rt-story-supplier-balance','rt-story-supplier-table','rt-story-hubs','rt-story-provenance',...['X','M'].flatMap(f=>['copy','takeaway','balance','donut','legend','declines','table'].map(part=>`rt-story-${f}-${part}`))])$('#'+id).replaceChildren();}
function storyURL(){const u=new URL(location.href);u.searchParams.set('story_country',story.country);if(story.year)u.searchParams.set('story_year',story.year);history.replaceState(null,'',u);}
function storyTable(basket,labels){return table([tr('Kategorie / země','Category / country'),'2019 USD',`${story.year} USD`,'Δ USD',tr('Podíl kladných změn','Share of positive changes')],basket.rows.map(r=>[esc(labels(r.code)),esc(decimal(r.baseExact)),esc(decimal(r.valueExact)),esc(decimal(r.deltaExact)),r.sharePositiveExact===null?'—':esc(r.sharePositiveExact)+'%']));}
function balance(basket,total=basket.netExact,fullBasket=false){return [[tr('Kladné změny','Positive changes'),basket.positiveExact],[tr('Poklesy','Declines'),basket.negativeExact],[fullBasket?tr('Čistá změna vykázaného koše','Net change in observed basket'):tr('Čistá změna společného panelu','Matched-panel net change'),total]].map(([label,value])=>`<div><small>${esc(label)}</small><strong>${esc(exactUSD(value))}</strong></div>`).join('');}
function storyPlot(id,slug,rows,{type='bar',title,color='#a8b63f',donut=false,denominator,axis}={}){
 const wrapper=$('#'+id);if(!rows.length){wrapper.innerHTML=`<p class="rt-note">${tr('Žádné doložené změny tohoto znaménka.','No observed changes of this sign.')}</p>`;return;}
 const host=document.createElement('div');wrapper.append(host);
 const supplier=id==='rt-story-suppliers'||id==='rt-story-supplier-declines',flow=id.includes('-M-')?'M':'X',sourceData=supplier?story.data:story.bilateral;
 const plotRows=rows.map(r=>({...r,reporter:supplier?r.code:story.country,flow,baselineYear:'2019',comparisonYear:story.year,denominatorExact:donut?denominator:null,baseLoadIds:r.baseLoadIds??r.baseObservation?.release_ids??null,valueLoadIds:r.valueLoadIds??r.valueObservation?.release_ids??null}));
 const columns=[...deltaColumns.map(c=>({...c,...(c.key==='valueExact'?{label:`${story.year} USD`}:{} )})),{key:'reporter',label:'Reporter ISO3'},{key:'flow',label:'Flow'},{key:'baselineYear',label:'Baseline year'},{key:'comparisonYear',label:'Comparison year'},{key:'denominatorExact',label:'Positive-change denominator USD'},{key:'baseLoadIds',label:'Baseline ingestion IDs'},{key:'valueLoadIds',label:'Endpoint ingestion IDs'}];
 const spec={type,rows:plotRows,fields:[{key:'delta',label:tr('Vypočtená změna','Calculated change'),format:(v,row)=>exactUSD(row.deltaExact)}],tableColumns:columns,yDomain:axis,title,unit:tr('Δ běžné USD','Δ current USD'),locale,inspectionPlacement:'below',height:donut?280:Math.max(180,rows.length*42+95),rowColor:row=>donut?row.color:color,...(donut?{shareFormat:(v,row)=>`${row.sharePositiveExact}%`,centerLabel:'≈ '+money(Number(denominator)),centerSubLabel:title.split(' · ')[0]}:{valueLabels:true,valueLabelFormat:v=>money(v)})};
 const chart=state.plot.render(host,spec);story.charts.push(chart);window.PSDChart.register({slug,el:wrapper,title,accessor:chart.accessor,exports:['csv','png'],embeddable:false,exportCaption:`${title} · 2019 → ${story.year} · current USD\n${donut?`Positive-change denominator: ${denominator} USD\n`:''}${rows.map(r=>`${r.label}: ${r.deltaExact} USD${donut?` (${r.sharePositiveExact}%)`:''}`).join('\n')}\nUN Comtrade · ${sourceData.source.table} · available original HS6 subtotals`,source:{...source(sourceData),definition:tr('Změna koncového roku proti 2019; přesná desetinná aritmetika.','Endpoint minus 2019; exact decimal arithmetic.'),caveat:tr('Podíl používá součet pouze kladných změn; chybějící konce jsou vynechány a pojmenovány.','Share uses the sum of positive changes only; missing endpoints are excluded and named.')}});
}
async function loadStory(){
 const request=++story.request;clearStory();$('#rt-story-retry').hidden=true;$('#rt-story-status').textContent=tr('Načítáme společný roční příběh…','Loading the shared annual story…');$('#rt-story-year').disabled=true;
 try{
  const aggregate=story.data?Promise.resolve(story.data):state.data?.frequency==='A'&&state.data.product==='TOTAL'?Promise.resolve(state.data):readRussiaAggregate('A','TOTAL');
  const bilateralData=story.cache.has(story.country)?Promise.resolve(story.cache.get(story.country)):bilateral.country===story.country&&bilateral.data?Promise.resolve(bilateral.data):readRussiaAggregate('A','TOTAL',fetch,`/api/v1/trade/russia-bilateral?country=${encodeURIComponent(story.country)}`);
  const [data,direct]=await Promise.all([aggregate,bilateralData]);if(request!==story.request)return;story.data=data;story.bilateral=direct;story.cache.set(story.country,direct);story.year=chooseStoryYear(data,direct,story.year)||'2024';
  const years=[...new Set([...data.suppliers.map(o=>o.period),story.year])].filter(y=>/^\d{4}$/.test(y)&&y>'2019').sort();$('#rt-story-year').innerHTML=years.map(y=>`<option value="${y}">${y}</option>`).join('');$('#rt-story-year').value=story.year;$('#rt-story-year').disabled=false;
  const select=$('#rt-story-country'),known=new Set([...select.options].map(o=>o.value));for(const code of [story.country,...new Set(data.suppliers.map(o=>o.reporter_iso3))])if(code!=='RUS'&&!known.has(code)){const option=document.createElement('option');option.value=code;select.append(option);known.add(code);}for(const option of select.options)option.textContent=`${country(option.value)} · ${option.value}`;select.value=story.country;
  renderStory();
 }catch(error){if(request!==story.request)return;clearStory();$('#rt-story-status').textContent=tr('Roční příběh se nepodařilo načíst.','The annual story could not be loaded.');$('#rt-story-retry').hidden=false;console.error('Russia delta story failed',error);}
}
function renderStory(){
 if(!story.data||!story.bilateral)return;clearStory();$('#rt-story-download').disabled=false;storyURL();const year=story.year,who=country(story.country),suppliers=supplierDelta(story.data,'2019',year),growth=suppliers.positives.slice(0,10).map(r=>({...r,label:country(r.code)}));
 $('#rt-story-status').textContent=tr(`Všechny panely: 2019 → ${year} · veškeré dostupné zboží · ročně · běžné USD. Nezávislé na měsíčních filtrech průzkumníku.`,`Every panel: 2019 → ${year} · all available goods · annual · current USD. Independent of the explorer’s monthly filters.`);
 const missing=suppliers.missing.map(r=>r.code).join(', ')||tr('žádné','none');$('#rt-story-supplier-copy').textContent=tr(`Deset největších přírůstků a poklesů se stejnou dolarovou škálou. Společný panel ${suppliers.knownCount} z ${suppliers.totalCount} pozorovaných dodavatelů; chybějící základ nebo konec: ${missing}. Nejde o úplný světový součet.`,`The ten largest observed dollar increases and declines, with equal dollar scales. Matched panel: ${suppliers.knownCount} of ${suppliers.totalCount} observed suppliers; missing baseline or endpoint: ${missing}. This is not a complete global total.`);
 const span=state.plot.domain(suppliers.rows.map(r=>Math.abs(r.delta??0))).max,ticks=state.plot.domain([span]).ticks;storyPlot('rt-story-suppliers','russia-story-supplier-increases',growth,{title:tr('Největší přírůstky dodávek do Ruska','Largest increases in supplies to Russia'),axis:{min:0,max:span,ticks}});storyPlot('rt-story-supplier-declines','russia-story-supplier-declines',suppliers.negatives.slice().sort((a,b)=>a.delta-b.delta).slice(0,10).map(r=>({...r,label:country(r.code)})),{title:tr('Největší poklesy dodávek do Ruska','Largest declines in supplies to Russia'),color:'#c93237',axis:{min:-span,max:0,ticks:ticks.map(v=>v===0?0:-v).reverse()}});$('#rt-story-supplier-balance').innerHTML=balance(suppliers);$('#rt-story-supplier-table').innerHTML=storyTable(suppliers,country);
 $('#rt-story-country-title').textContent=tr(`${who}: rozložte změnu na zboží.`,`${who}: take the change apart.`);
 for(const flow of ['X','M']){
  const basket=bilateralDelta(story.bilateral,{country:story.country,flow,baseYear:'2019',endYear:year}),direction=flow==='X'?`${who} → ${country('RUS')}`:`${country('RUS')} → ${who}`,label=code=>code==='OTHER'?tr('Ostatní rostoucí kategorie','Other growing categories'):`${productName(code)} · HS ${code}`,slices=deltaSlices(basket).map((r,i)=>({...r,label:label(r.code),color:storyPalette[i],memberCodes:r.members.join('|')}));
  $('#rt-story-'+flow+'-title').textContent=direction;const top=basket.positives[0];$('#rt-story-'+flow+'-takeaway').textContent=top?tr(`${productName(top.code)} představují největší doložený přírůstek: +${exactUSD(top.deltaExact)}.`,`${productName(top.code)} contributed the largest observed increase: +${exactUSD(top.deltaExact)}.`):tr('Pro tento rok chybí srovnatelný kladný přírůstek.','No paired positive category increase is available for this year.');const diff=basket.coverageDifferenceExact,missing=basket.missing.map(r=>r.code).join(', ')||tr('žádné','none');
  $('#rt-story-'+flow+'-copy').textContent=tr(`Koš: ${exactUSD(basket.total?.baseExact)} → ${exactUSD(basket.total?.valueExact)}. Podíl kruhu = přírůstek kategorie / ${exactUSD(basket.positiveExact)} kladných změn. Srovnatelné kategorie ${basket.knownCount}/${basket.totalCount}; chybějící: ${missing}. Čistá změna srovnatelných kategorií: ${exactUSD(basket.netExact)}. Rozdíl mezi čistou změnou koše a srovnatelnými kategoriemi: ${exactUSD(diff)}.`,`Observed basket: ${exactUSD(basket.total?.baseExact)} → ${exactUSD(basket.total?.valueExact)}. Donut share = category increase / ${exactUSD(basket.positiveExact)} of positive changes. Paired categories ${basket.knownCount}/${basket.totalCount}; missing: ${missing}. Paired-category net change: ${exactUSD(basket.netExact)}. Difference between full-basket net change and paired-category net change: ${exactUSD(diff)}.`);
  $('#rt-story-'+flow+'-balance').innerHTML=balance(basket,basket.total?.deltaExact??null,true);
  storyPlot('rt-story-'+flow+'-donut',({X:'russia-story-exports-growth',M:'russia-story-imports-growth'})[flow],slices,{type:'donut',donut:true,title:`${direction} · ${tr('podíl kladných změn','share of positive changes')}`,denominator:basket.positiveExact});
  $('#rt-story-'+flow+'-legend').innerHTML=table([tr('Rostoucí kategorie','Growing category'),'Δ USD',tr('Podíl kladných změn','Share of positive changes')],slices.map(r=>[`<i style="background:${r.color}"></i>${esc(r.label)}`,esc(decimal(r.deltaExact)),esc(decimal(r.sharePositiveExact))+'%']));
  storyPlot('rt-story-'+flow+'-declines',({X:'russia-story-exports-declines',M:'russia-story-imports-declines'})[flow],basket.negatives.slice().sort((a,b)=>a.delta-b.delta).slice(0,5).map(r=>({...r,label:label(r.code)})),{title:`${direction} · ${tr('pět největších poklesů','five largest declines')}`,color:'#c93237'});
  $('#rt-story-'+flow+'-table').innerHTML=storyTable(basket,label);
 }
 $('#rt-story-hubs').innerHTML=HUBS.map(hub=>{const basket=hubDelta(story.data,hub,'2019',year);return `<section><h4>${esc(country(hub))}</h4>${table([tr('Samostatný tok','Separate flow'),'2019 USD',`${year} USD`,'Δ USD'],basket.rows.map(r=>[r.code==='WORLD_IMPORTS'?tr('Dovoz ze světa','World imports'):tr('Vývoz do Ruska','Exports to Russia'),esc(decimal(r.baseExact)),esc(decimal(r.valueExact)),esc(decimal(r.deltaExact))]))}</section>`;}).join('');
 const ids=[...new Set([...(story.data.source.release_ids||[]),...(story.bilateral.source.release_ids||[])])];$('#rt-story-provenance').textContent=`${story.data.source.table}. ${story.bilateral.source.method||''} ${story.bilateral.source.release_note||''} ${tr('Vydání načtení','Ingestion IDs')}: ${ids.join(' | ')}. ${tr('Každá změna je konec minus základ. Součty a rozdíly používají původní desetinné řetězce, nikoli zaokrouhlené popisky grafu. Podíly jsou vypočtené a zobrazené nejvýše na devět desetinných míst.','Every change is endpoint minus baseline. Sums and differences use original decimal strings, never rounded chart labels. Shares are calculated and displayed to at most nine decimal places.')}`;
}
$('#rt-story-country').addEventListener('change',e=>{story.country=e.target.value;loadStory();});$('#rt-story-year').addEventListener('change',e=>{story.year=e.target.value;renderStory();});$('#rt-story-retry').addEventListener('click',loadStory);
$('#rt-story-download').addEventListener('click',()=>{
 if(!story.data||!story.bilateral)return;const year=story.year;
 const rows=deltaAuditRows(supplierDelta(story.data,'2019',year),{kind:'direct_supplier',flow:'X'});
 for(const flow of ['X','M']){const basket=bilateralDelta(story.bilateral,{country:story.country,flow,endYear:year});rows.push(...deltaAuditRows(basket,{reporter:story.country,flow}));const total=deltaBasket(story.bilateral.observations.filter(o=>o.reporter_iso3===story.country&&o.partner_iso3==='RUS'&&o.flow_code===flow&&o.product_code==='TOTAL'),{endYear:year});rows.push(...deltaAuditRows(total,{kind:'observed_basket',reporter:story.country,flow}));}
 for(const hub of HUBS)for(const row of deltaAuditRows(hubDelta(story.data,hub,'2019',year),{kind:'hub_route',reporter:hub}))rows.push({...row,flow_code:row.code==='WORLD_IMPORTS'?'M':'X',positive_denominator_usd:null,declines_usd:null,paired_net_usd:null,share_positive_pct:null});
 const csv=window.PSDChart.toCSV(Object.keys(rows[0]||{}).map(key=>({key,label:key})),rows),url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'})),link=document.createElement('a');link.href=url;link.download=`russia-delta-2019-${year}-${story.country}.csv`;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);
});
$('#rt-story-explore').addEventListener('click',()=>{if(!state.model)return;state.frequency='A';state.product='TOTAL';state.period=story.year;controls();load();});

start();
